  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'soil', 4, $j${"emoji":"🪴","name":{"ha":"Cika da ƙasa","en":"Fill with soil"},"text":{"ha":"Ana cika ta da ƙasa mai kyau.","en":"Fill it with good soil."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'seed', 5, $j${"emoji":"🌻","name":{"ha":"Shuka iri","en":"Plant a seed"},"text":{"ha":"Ana shuka iri a ƙasa a yi masa ruwa kaɗan.","en":"Plant a seed in the soil and add a little water."},"kid":true}$j$::jsonb);
