  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🍌","kind":"resource","name":{"ha":"Bawon ayaba","en":"Banana peels"},"why":{"ha":"Bawon ayaba yana fitowa daga tsiro. Abu na asali ne.","en":"Banana peels come from a plant. They are a resource."}},{"emoji":"🍂","kind":"product","name":{"ha":"Taki","en":"Compost"},"why":{"ha":"Ana yin taki daga ragowar tsirrai. Sabon abu ne.","en":"Compost is made from plant scraps. It is a new product."}},{"emoji":"🥬","kind":"resource","name":{"ha":"Ragowar kayan lambu","en":"Vegetable scraps"},"why":{"ha":"Ragowar kayan lambu za a iya sake amfani da su. Abu na asali ne.","en":"Vegetable scraps can be used again. They are a resource."}},{"emoji":"🌿","kind":"product","name":{"ha":"Ganyen rufe ƙasa","en":"Leaf mulch"},"why":{"ha":"An yi shi daga busasshen ganye don kare ƙasa. Sabon abu ne.","en":"It is made from dry leaves to protect soil. It is a new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🧼","kind":"safe","name":{"ha":"Wanke hannu bayan taɓa shara","en":"Wash hands after touching waste"},"why":{"ha":"Wannan lafiya ne kuma yana da muhimmanci.","en":"This is safe and important."}},{"emoji":"💧","kind":"safe","name":{"ha":"Yayyafa ruwa a tarin taki","en":"Sprinkle water on the heap"},"why":{"ha":"Yayyafa ruwa lafiya ne.","en":"Sprinkling water is safe."}},{"emoji":"⛏️","kind":"adult","name":{"ha":"Haƙa ƙasa da fartanya","en":"Dig the ground with a spade"},"why":{"ha":"Fartanya tana da nauyi da kaifi. Babba ne kawai.","en":"A spade is heavy and sharp. Only an adult."}},{"emoji":"🐕","kind":"adult","name":{"ha":"Kashin dabba a cikin ganye","en":"Animal droppings among the leaves"},"why":{"ha":"Kada ka taɓa shi. Ka gaya wa babba.","en":"Do not touch it. Tell an adult."}},{"emoji":"🌵","kind":"adult","name":{"ha":"Ƙaya ko ciyawa mai kaifi","en":"Thorns or sharp grass"},"why":{"ha":"Za su iya yanka hannu. Ka kira babba.","en":"They can cut your hand. Call an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Menene shara ta halitta?","en":"What is organic waste?"}$j$::jsonb, $j$[{"ha":"Ragowar tsirrai da abinci da ke ruɓewa","en":"Plant and food scraps that rot naturally"},{"ha":"Kwalbar filastik","en":"A plastic bottle"},{"ha":"Gilashin da ya karye","en":"Broken glass"}]$j$::jsonb, 0, $j${"ha":"Shara ta halitta tana fitowa daga tsirrai da abinci kuma tana ruɓewa.","en":"Organic waste comes from plants and food, and it rots."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wane ne za a iya saka a cikin taki?","en":"Which one can go into compost?"}$j$::jsonb, $j$[{"ha":"Jakar filastik","en":"A plastic bag"},{"ha":"Bawon ayaba","en":"Banana peel"},{"ha":"Batir","en":"A battery"}]$j$::jsonb, 1, $j${"ha":"Bawon ayaba yana ruɓewa. Filastik da batir ba sa ruɓewa.","en":"Banana peel rots. Plastic and batteries do not."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa ake juya tarin taki?","en":"Why do we turn the compost pile?"}$j$::jsonb, $j$[{"ha":"Don ya yi nauyi","en":"To make it heavy"},{"ha":"Don ƙudaje su zo","en":"To bring flies"},{"ha":"Don iska ta shiga","en":"So air can get in"}]$j$::jsonb, 2, $j${"ha":"Ƙananan masu taimako suna buƙatar iska don su mayar da ragowar taki.","en":"The tiny helpers need air to turn the scraps into compost."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Wane ne busasshe a cikin kayan taki?","en":"Which one is a dry “brown” material?"}$j$::jsonb, $j$[{"ha":"Sabon bawon kayan lambu","en":"Fresh vegetable peels"},{"ha":"Busasshen ganye","en":"Dry leaves"},{"ha":"Sabuwar ciyawa","en":"Fresh grass"}]$j$::jsonb, 1, $j${"ha":"Busasshen ganye busasshe ne. Bawo da sabuwar ciyawa kuma danye ne.","en":"Dry leaves are brown. Peels and fresh grass are green."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Me ya sa ba a saka nama da mai a taki?","en":"Why do we not add meat and oil to compost?"}$j$::jsonb, $j$[{"ha":"Suna jawo ƙudaje da beraye kuma suna wari","en":"They attract flies and rats and smell bad"},{"ha":"Suna sa taki ya fi kyau","en":"They make it better"},{"ha":"Suna ƙara iska","en":"They add air"}]$j$::jsonb, 0, $j${"ha":"Nama da mai ba su dace da tarin taki ba.","en":"Meat and oil do not belong in a compost pile."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wa ke haƙa ko juya tarin taki da farfaru?","en":"Who digs or turns the pile with a fork?"}$j$::jsonb, $j$[{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"},{"ha":"Babba","en":"An adult"}]$j$::jsonb, 2, $j${"ha":"Kayan aiki suna da nauyi da kaifi. Babba ne kawai ke yi.","en":"Tools are heavy and sharp. Only an adult does it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ɗanshin tarin taki ya kamata ya kasance?","en":"How wet should a compost pile feel?"}$j$::jsonb, $j$[{"ha":"Ya jiƙe sosai kamar tafki","en":"Soaking wet like a pond"},{"ha":"Kamar soso da aka matse","en":"Like a squeezed sponge"},{"ha":"Ya bushe ƙwarai","en":"Completely dry"}]$j$::jsonb, 1, $j${"ha":"Ɗanshi kaɗan yana taimaka wa ƙananan halittu aiki.","en":"A little moisture helps the tiny helpers work."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🌾","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A wani ƙauye, yara ba su iya karatu da dare. Fitilu suna ƙarewa kuma kananzir yana da tsada.","en":"In a village, children cannot study at night. Lamps run out and kerosene is expensive."}},{"text":{"ha":"Rana tana haskakawa kyauta kowace rana. Za ka iya taimaka musu su yi amfani da ita?","en":"The sun shines for free every day. Can you help them use it?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"☀️","title":{"ha":"Hasken rana abu na asali ne","en":"Sunlight is a resource"},"lines":[{"text":{"ha":"Hasken rana yana zuwa kyauta kowace rana. Abu na asali ne.","en":"Sunlight comes free every day. It is a resource."}},{"text":{"ha":"Idan an sarrafa shi da faifan rana, sai ya zama wutar lantarki, sabon abu mai amfani.","en":"When we process it with a solar panel, it becomes electricity, a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🔆","title":{"ha":"Makamashin rana","en":"Solar energy"},"lines":[{"text":{"ha":"Makamashin rana wuta ce da ake samu daga hasken rana.","en":"Solar energy is power we get from sunlight."}},{"text":{"ha":"Faifan rana yana juya haske zuwa wutar lantarki.","en":"A solar panel turns light into electricity."}},{"text":{"ha":"Yana aiki ba tare da hayaƙi ba, kuma rana ba ta ƙarewa.","en":"It works without smoke, and the sun does not run out."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada ka kalli rana kai tsaye, har da ta gilashin ƙara girma. Yana cutar da ido.","en":"Never look straight at the sun, not even through a magnifying glass. It hurts your eyes."}},{"text":{"ha":"Kada ka taɓa wayoyi ko baturi, kuma kada ka hau rufi. Ƙwararre babba ne kawai ke girkawa. Wannan wasa ne kawai.","en":"Do not touch wires or batteries, and do not climb on a roof. Only a trained adult installs. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🔲","title":{"ha":"Faifan rana","en":"Solar panel"},"lines":[{"k":"whatIs","text":{"ha":"Faifai mai ƙananan sel da ke ɗaukar hasken rana.","en":"A flat board with small cells that catch sunlight."}},{"k":"whatDoes","text":{"ha":"Yana mayar da haske zuwa wutar lantarki.","en":"It turns light into electricity."}},{"k":"whyNeeded","text":{"ha":"Yana ba da wuta a wuraren da babu layin wuta.","en":"It gives power where there is no power line."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🔋","title":{"ha":"Baturi","en":"Battery"},"lines":[{"k":"whatIs","text":{"ha":"Akwati da ke adana wutar lantarki.","en":"A box that stores electricity."}},{"k":"whatDoes","text":{"ha":"Yana adana wuta da rana don a yi amfani da ita da dare.","en":"It saves power in the day so we can use it at night."}},{"k":"whyNeeded","text":{"ha":"Ba tare da baturi ba, wuta tana ƙarewa da zarar rana ta faɗi.","en":"Without a battery, the power stops as soon as the sun sets."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"💡","title":{"ha":"Fitila da na’urar kula","en":"Lamp and controller"},"lines":[{"text":{"ha":"Fitilar LED tana haske da ɗan wuta kaɗan.","en":"An LED lamp shines using very little power."}},{"text":{"ha":"Na’urar kula tana hana baturi cika fiye da kima ko ƙarewa gaba ɗaya.","en":"The controller stops the battery from overfilling or running completely flat."}},{"text":{"ha":"Faifai → Na’urar kula → Baturi → Fitila","en":"Panel → Controller → Battery → Lamp"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"📍","title":{"ha":"Inda ake ɗora faifai","en":"Where to place a panel"},"lines":[{"text":{"ha":"Faifai yana buƙatar rana sosai, ba inuwa ba.","en":"A panel needs plenty of sun and no shade."}},{"text":{"ha":"Ana karkatar da shi zuwa rana kuma a kiyaye shi daga ƙura.","en":"It is tilted towards the sun and kept free of dust."}},{"text":{"ha":"Ko da gajimare, faifai yana ba da ɗan wuta, amma ƙasa da lokacin rana mai ƙarfi.","en":"Even on cloudy days a panel gives some power, but less than in strong sun."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Faifan rana yana rage kuɗin kananzir da batir.","en":"A solar panel cuts the cost of kerosene and batteries."}},{"text":{"ha":"Mutum zai iya buɗe wurin cajin waya ya sayar da sabis.","en":"A person can open a phone-charging point and sell the service."}},{"text":{"ha":"Busar da abinci da rana yana sa mangwaro da tumatir su daɗe, kuma ana iya sayarwa. Za ka kalle su duka.","en":"Drying food in the sun makes mango and tomato last longer, and it can be sold. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'findSun', 0, $j${"emoji":"🌞","name":{"ha":"A nemi wurin rana","en":"Find a sunny spot"},"text":{"ha":"A nemi wuri mai hasken rana da ba shi da inuwa.","en":"Find a place with full sunshine and no shade."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'mountPanel', 1, $j${"emoji":"🔆","name":{"ha":"A ɗora faifan rana","en":"Mount the panel"},"text":{"ha":"Babba yana ɗora faifan a kan tsayayyen goyon baya, ya karkatar da shi zuwa rana.","en":"An adult fixes the panel on a firm support, tilted towards the sun."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'wireController', 2, $j${"emoji":"🔌","name":{"ha":"A haɗa na’urar kula","en":"Connect the controller"},"text":{"ha":"Ƙwararre yana haɗa wayoyi zuwa na’urar kula da caji.","en":"A trained technician connects the wires to the charge controller."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'connectBattery', 3, $j${"emoji":"🔋","name":{"ha":"A haɗa baturi","en":"Connect the battery"},"text":{"ha":"Ƙwararre yana haɗa baturi don ya adana wuta.","en":"A trained technician connects a battery to store the power."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'connectLamp', 4, $j${"emoji":"💡","name":{"ha":"A haɗa fitila","en":"Connect the lamp"},"text":{"ha":"Ƙwararre yana haɗa fitilar LED.","en":"A trained technician connects the LED lamp."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plugUSB', 5, $j${"emoji":"📱","name":{"ha":"A saka cajar waya","en":"Plug in the phone charger"},"text":{"ha":"Babba yana saka wayar a mashigar USB.","en":"An adult plugs the phone into the USB socket."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'chargeDay', 6, $j${"emoji":"⏳","name":{"ha":"A bar ta yi caji da rana","en":"Let it charge in the day"},"text":{"ha":"Faifan yana tara hasken rana yana cika baturi cikin yini.","en":"The panel gathers sunlight and fills the battery during the day."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'nightUse', 7, $j${"emoji":"🌙","name":{"ha":"A kunna da dare","en":"Switch on at night"},"text":{"ha":"Da dare, a kunna fitilar tare da babba kusa.","en":"At night, switch on the lamp with an adult nearby."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'prepFood', 8, $j${"emoji":"🔪","name":{"ha":"A yanka abinci","en":"Slice the food"},"text":{"ha":"Babba yana wanke yana yanka mangwaro ko tumatir siraran guntu.","en":"An adult washes and slices mango or tomato into thin pieces."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'spreadTray', 9, $j${"emoji":"🧺","name":{"ha":"A shimfiɗa a kan tire","en":"Spread on a tray"},"text":{"ha":"A shimfiɗa guntun a kan tire mai tsabta, kada su taru.","en":"Spread the pieces on a clean tray, not touching each other."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'coverNet', 10, $j${"emoji":"🕸️","name":{"ha":"A rufe da raga","en":"Cover with a net"},"text":{"ha":"A rufe da raga mai tsabta don kare shi daga ƙudaje da ƙura.","en":"Cover with a clean net to keep off flies and dust."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'dryInSun', 11, $j${"emoji":"☀️","name":{"ha":"A bushar da rana","en":"Dry in the sun"},"text":{"ha":"A bar tire a rana na kwanaki har abincin ya bushe.","en":"Leave the tray in the sun for days until the food is dry."},"kid":true}$j$::jsonb);
