  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'lamp', 0, $j${"id":"lamp","emoji":"💡","name":{"ha":"Fitilar rana","en":"Solar lamp"},"steps":["findSun","mountPanel","wireController","connectBattery","connectLamp","chargeDay","nightUse"],"result":{"emoji":"💡","name":{"ha":"Hasken fitila da dare","en":"Light at night"}},"summary":{"ha":"Fitilar rana: faifan yana caji da rana, baturi yana adana, fitila tana haske da dare.","en":"Solar lamp: the panel charges in the day, the battery stores it, the lamp shines at night."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'phone', 1, $j${"id":"phone","emoji":"📱","name":{"ha":"Wurin cajin waya","en":"Phone charging point"},"steps":["findSun","mountPanel","wireController","connectBattery","plugUSB","chargeDay"],"result":{"emoji":"🔌","name":{"ha":"Cajin waya da rana","en":"Phone charging by sun"}},"summary":{"ha":"Wurin cajin waya: faifan rana yana ba da wuta ga mashigar USB ta hanyar na’urar kula.","en":"Phone charging point: the panel powers a USB socket through the controller."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'dryer', 2, $j${"id":"dryer","emoji":"🥭","name":{"ha":"Busar da abinci da rana","en":"Solar food drying"},"steps":["prepFood","spreadTray","coverNet","dryInSun","storeDry"],"result":{"emoji":"🥭","name":{"ha":"Busasshen mangwaro","en":"Dried mango"}},"summary":{"ha":"Busar da abinci: a yanka, a shimfiɗa, a rufe, a bushar da rana, a adana.","en":"Solar drying: slice, spread, cover, dry in the sun and store."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'care', 3, $j${"id":"care","emoji":"🧽","name":{"ha":"Kula da faifan rana","en":"Caring for the panel"},"steps":["checkDirt","wipePanel","checkWires","keepClear"],"result":{"emoji":"✨","name":{"ha":"Faifai mai aiki da kyau","en":"A panel that works well"}},"summary":{"ha":"Kula: a duba datti, a goge, ƙwararre yana duba wayoyi, a hana inuwa.","en":"Care: check dirt, wipe, a technician checks wires, keep shade away."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"☀️","kind":"resource","name":{"ha":"Hasken rana","en":"Sunlight"},"why":{"ha":"Rana tana ba da haske kyauta. Abu na asali ne.","en":"The sun gives light for free. It is a resource."}},{"emoji":"💡","kind":"product","name":{"ha":"Fitilar rana","en":"Solar lamp"},"why":{"ha":"An yi ta daga faifan rana da baturi. Sabon abu ne.","en":"It is made from a panel and a battery. It is a new product."}},{"emoji":"🥭","kind":"resource","name":{"ha":"Mangwaro sabo","en":"Fresh mango"},"why":{"ha":"Yana fitowa daga itace. Abu na asali ne.","en":"It comes from a tree. It is a resource."}},{"emoji":"🍑","kind":"product","name":{"ha":"Busasshen mangwaro","en":"Dried mango"},"why":{"ha":"An bushar da shi da rana. Sabon abu ne.","en":"It was dried in the sun. It is a new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🌳","kind":"safe","name":{"ha":"Zauna a inuwa lokacin zafi","en":"Sit in the shade when it is hot"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🧺","kind":"safe","name":{"ha":"Shimfiɗa busasshen abinci a tire","en":"Spread food on a drying tray"},"why":{"ha":"Wannan lafiya ne idan abincin mai tsabta ne.","en":"This is safe when the food is clean."}},{"emoji":"🕶️","kind":"adult","name":{"ha":"Kalli rana kai tsaye","en":"Look straight at the sun"},"why":{"ha":"Kada ka yi. Yana cutar da ido. Ka gaya wa babba.","en":"Never do it. It hurts your eyes. Tell an adult."}},{"emoji":"🪜","kind":"adult","name":{"ha":"Hau rufi don gyara faifai","en":"Climb on a roof to fix a panel"},"why":{"ha":"Faɗuwa tana da haɗari. Ƙwararre babba ne kawai.","en":"Falling is dangerous. Only a trained adult."}},{"emoji":"🔌","kind":"adult","name":{"ha":"Taɓa wayoyi da hannu mai ruwa","en":"Touch wires with wet hands"},"why":{"ha":"Ruwa da wutar lantarki haɗari ne. Ka kira babba.","en":"Water and electricity are dangerous together. Call an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Menene makamashin rana?","en":"What is solar energy?"}$j$::jsonb, $j$[{"ha":"Wuta da ake samu daga hasken rana","en":"Power we get from sunlight"},{"ha":"Wuta daga gawayi","en":"Power from charcoal"},{"ha":"Iska daga fanka","en":"Wind from a fan"}]$j$::jsonb, 0, $j${"ha":"Faifan rana yana juya hasken rana zuwa wutar lantarki.","en":"A solar panel turns sunlight into electricity."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me faifan rana yake yi?","en":"What does a solar panel do?"}$j$::jsonb, $j$[{"ha":"Yana tace ruwa","en":"It filters water"},{"ha":"Yana mayar da haske zuwa wutar lantarki","en":"It turns light into electricity"},{"ha":"Yana kiwon kifi","en":"It raises fish"}]$j$::jsonb, 1, $j${"ha":"Sel ɗin faifan suna ɗaukar haske su mayar da shi wuta.","en":"The cells in the panel catch light and turn it into power."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa ake amfani da baturi?","en":"Why do we use a battery?"}$j$::jsonb, $j$[{"ha":"Don ya yi nauyi","en":"To make it heavy"},{"ha":"Don ya yi ƙara","en":"To make noise"},{"ha":"Don adana wuta a yi amfani da ita da dare","en":"To store power for use at night"}]$j$::jsonb, 2, $j${"ha":"Baturi yana adana wutar da faifan ya samu da rana.","en":"The battery keeps the power the panel made in the day."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Ina ya fi dacewa a ɗora faifan rana?","en":"Where is the best place for a solar panel?"}$j$::jsonb, $j$[{"ha":"A cikin inuwa","en":"In the shade"},{"ha":"Wuri mai rana ba inuwa","en":"A sunny place with no shade"},{"ha":"A cikin rami","en":"In a hole"}]$j$::jsonb, 1, $j${"ha":"Inuwa tana rage wutar da faifan ke bayarwa.","en":"Shade reduces the power the panel gives."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Me ya kamata ka yi game da rana mai ƙarfi?","en":"What should you do about strong sunlight?"}$j$::jsonb, $j$[{"ha":"Ka guji kallon rana kai tsaye","en":"Never look straight at the sun"},{"ha":"Ka kalle ta kai tsaye","en":"Look straight at it"},{"ha":"Ka kalle ta ta gilashin ƙara girma","en":"Look at it through a magnifying glass"}]$j$::jsonb, 0, $j${"ha":"Kallon rana yana cutar da ido har ta hanyar gilashi.","en":"Looking at the sun hurts your eyes, even more through a lens."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wa ke girka faifan rana a rufi?","en":"Who installs a solar panel on a roof?"}$j$::jsonb, $j$[{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"},{"ha":"Ƙwararre babba","en":"A trained adult"}]$j$::jsonb, 2, $j${"ha":"Rufi da wayoyi suna da haɗari. Ƙwararre ne kawai ke yi.","en":"Roofs and wires are dangerous. Only a trained person does it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Me ya sa busar da abinci da rana yake da amfani?","en":"Why is drying food in the sun useful?"}$j$::jsonb, $j$[{"ha":"Yana sa abinci ya daɗe kuma za a iya sayarwa","en":"It makes food last and it can be sold"},{"ha":"Yana sa abinci ya ruɓe","en":"It makes food rot"},{"ha":"Yana ƙara ruwa a abinci","en":"It adds water to food"}]$j$::jsonb, 0, $j${"ha":"Abincin da ya bushe yana daɗewa kafin ya lalace.","en":"Dry food lasts longer before it spoils."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🏫","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Malamarmu tana son ƙaramin mutum-mutumi da zai taimaka a aji.","en":"Our teacher wants a small robot to help in class."}},{"text":{"ha":"Za mu gina shi daga tsofaffin kayan da aka jefar. Za ka iya taimaka mana?","en":"We will build it from old things people threw away. Can you help us?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"♻️","title":{"ha":"Tsofaffin kaya abu na asali ne","en":"Old things are resources"},"lines":[{"text":{"ha":"Kwali, murfin kwalba da tsofaffin kayan wasa abubuwan asali ne.","en":"Cardboard, bottle caps and old toys are resources."}},{"text":{"ha":"Idan an sarrafa su, sai su zama robot, sabon abu mai amfani.","en":"When we process them, they become a robot, a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🤖","title":{"ha":"Menene robot?","en":"What is a robot?"},"lines":[{"text":{"ha":"Robot na’ura ce da ke bin umarni don yin aiki.","en":"A robot is a machine that follows instructions to do a job."}},{"text":{"ha":"Yawancin robot suna ganewa, suna tunani, sannan su yi aiki.","en":"Most robots sense, think, and then act."}},{"text":{"ha":"Robot ba mai rai ba ne. Mutane ne ke gina shi da shirya shi.","en":"A robot is not alive. People build it and program it."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🔩","title":{"ha":"Sassan robot","en":"Parts of a robot"},"lines":[{"text":{"ha":"Injin yana ba da motsi.","en":"The motor gives movement."}},{"text":{"ha":"Baturi yana ba da wutar lantarki.","en":"The battery gives electricity."}},{"text":{"ha":"Maɓalli yana kunnawa da kashewa, jiki kuma yana riƙe komai.","en":"The switch turns it on and off, and the body holds everything together."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada ka sa baturi a baki, musamman ƙaramin baturin maɓalli. Yana da haɗari sosai.","en":"Never put a battery in your mouth, especially a small button battery. It is very dangerous."}},{"text":{"ha":"Kaifi, manne mai zafi da walda na manya ne kawai. Yaro yana taimako kawai a kusa da babba. Wannan wasa ne kawai.","en":"Sharp tools, hot glue and soldering are for adults only. A child only helps with an adult nearby. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🧠","title":{"ha":"Robot yana bin umarni","en":"A robot follows instructions"},"lines":[{"text":{"ha":"Shirin robot jerin umarni ne mataki-mataki.","en":"A robot’s program is a list of instructions, step by step."}},{"text":{"ha":"Idan umarni ya yi kuskure, robot ma ya yi kuskure.","en":"If an instruction is wrong, the robot does the wrong thing."}},{"text":{"ha":"Gyara kuskuren shirin ana kiransa debugging.","en":"Fixing a mistake in a program is called debugging."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"👀","title":{"ha":"Na’urar ganewa","en":"Sensors"},"lines":[{"text":{"ha":"Na’urar ganewa (sensor) tana ba robot ji, kamar haske ko taɓawa.","en":"A sensor gives a robot a sense, like light or touch."}},{"text":{"ha":"Robot mai na’urar haske zai iya bin haske, ya tsaya idan ya taɓa abu.","en":"A robot with a light sensor can follow light, or stop when it touches something."}},{"text":{"ha":"A wannan aikin za mu koyi umarni da gina jiki da injin.","en":"In this mission we learn instructions and building the body and motor."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🏭","title":{"ha":"Robot a rayuwa","en":"Robots in real life"},"lines":[{"text":{"ha":"Ana amfani da robot a masana’antu, gonaki da asibitoci.","en":"Robots are used in factories, farms and hospitals."}},{"text":{"ha":"Suna taimakawa da aiki mai nauyi ko mai maimaitawa.","en":"They help with heavy or repeating work."}},{"text":{"ha":"Mutane ne ke ƙera su, shirya su da gyara su.","en":"People design, program and repair them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Tsofaffin kwali da murfi ba su da amfani, amma robot na wasa ko na koyarwa yana da ƙima.","en":"Old cardboard and caps earn nothing, but a toy or teaching robot has value."}},{"text":{"ha":"Matashi mai fasaha zai iya koyar da yara ko gyara na’urori ya samu kuɗi.","en":"A skilled young person can teach children or repair devices and earn money."}},{"text":{"ha":"Kowanne yana da hanyarsa. Za ka kalle su duka.","en":"Each one has its own way of being made. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sketch', 0, $j${"emoji":"✏️","name":{"ha":"A zana shirin","en":"Draw the plan"},"text":{"ha":"A zana robot ɗin da kake so da sassansa.","en":"Draw the robot you want and its parts."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'collectParts', 1, $j${"emoji":"📦","name":{"ha":"A tattara sassa","en":"Collect parts"},"text":{"ha":"A tattara kwali, murfin kwalba da tsofaffin kayan da za a sake amfani da su.","en":"Collect cardboard, bottle caps and old things to reuse."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cutBody', 2, $j${"emoji":"✂️","name":{"ha":"A yanka jikin","en":"Cut the body"},"text":{"ha":"Babba yana yanka kwali ko kofi don ya zama jikin robot.","en":"An adult cuts cardboard or a cup to make the robot body."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'fixMotor', 3, $j${"emoji":"⚙️","name":{"ha":"A manne injin","en":"Fix the motor"},"text":{"ha":"Babba yana manne ƙaramin injin a jikin robot.","en":"An adult fixes a small motor to the robot body."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'addWheels', 4, $j${"emoji":"🛞","name":{"ha":"A saka ƙafafu","en":"Add the wheels"},"text":{"ha":"A saka murfin kwalba a matsayin ƙafafu a kan ƙarfen injin, tare da babba.","en":"Put bottle caps on the motor axle as wheels, with an adult."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'addWeight', 5, $j${"emoji":"⚖️","name":{"ha":"A saka ɗan nauyi","en":"Add a small weight"},"text":{"ha":"A manne ƙaramin nauyi a gefe ɗaya na injin don ya girgiza.","en":"Tape a small weight to one side of the motor so it shakes."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'wireSwitch', 6, $j${"emoji":"🔌","name":{"ha":"A haɗa waya da maɓalli","en":"Wire the switch"},"text":{"ha":"Babba yana haɗa wayoyi da maɓalli.","en":"An adult connects the wires and the switch."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'putBattery', 7, $j${"emoji":"🔋","name":{"ha":"A saka baturi","en":"Insert the battery"},"text":{"ha":"Babba yana saka baturin AA a wurinsa. Ba a taɓa ƙaramin baturin maɓalli.","en":"An adult inserts the AA battery. Small button batteries are never touched."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'testRun', 8, $j${"emoji":"▶️","name":{"ha":"A gwada","en":"Test it"},"text":{"ha":"A kunna maɓallin a ƙasa mai santsi, babba yana kusa.","en":"Press the switch on a smooth floor with an adult nearby."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'fixBug', 9, $j${"emoji":"🔎","name":{"ha":"A nemo matsalar","en":"Find the problem"},"text":{"ha":"Idan bai yi aiki ba, a gaya wa babba ya duba wayoyi da baturi.","en":"If it does not work, ask an adult to check the wires and the battery."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cutStrips', 10, $j${"emoji":"📏","name":{"ha":"A yanka dogayen kwali","en":"Cut cardboard strips"},"text":{"ha":"Babba yana yanka kwali ya zama dogayen sanduna.","en":"An adult cuts cardboard into long strips."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'joinArm', 11, $j${"emoji":"📎","name":{"ha":"A haɗa hannu","en":"Join the arm"},"text":{"ha":"A haɗa sandunan da ƙusoshin takarda don su motsa.","en":"Join the strips with paper fasteners so they can move."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'attachSyringe', 12, $j${"emoji":"💉","name":{"ha":"A manne sirinji","en":"Attach the syringes"},"text":{"ha":"A manne sirinji marasa allura da bututu a hannun. Ba a taɓa allura.","en":"Attach needle-free syringes and tubing to the arm. Never touch a needle."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'fillWater', 13, $j${"emoji":"💧","name":{"ha":"A cika da ruwa","en":"Fill with water"},"text":{"ha":"A cika sirinji da bututu da ruwa mai tsabta.","en":"Fill the syringes and tubing with clean water."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'pressMove', 14, $j${"emoji":"👉","name":{"ha":"A matsa a ga hannu yana motsi","en":"Press and watch it move"},"text":{"ha":"A matsa sirinji ɗaya don hannun ya ɗaga.","en":"Press one syringe to make the arm lift."},"kid":true}$j$::jsonb);
