  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'makeCards', 16, $j${"emoji":"🃏","name":{"ha":"A yi katunan umarni","en":"Make command cards"},"text":{"ha":"A rubuta katunan: gaba, hagu, dama.","en":"Write cards: forward, left, right."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'writeProgram', 17, $j${"emoji":"🧠","name":{"ha":"A rubuta shirin umarni","en":"Write the program"},"text":{"ha":"A jera katunan don robot ya isa wurin da aka nufa.","en":"Line up the cards so the robot reaches the goal."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'runProgram', 18, $j${"emoji":"🤖","name":{"ha":"Aboki ya zama robot","en":"A friend acts as the robot"},"text":{"ha":"Aboki yana bin katunan daidai kamar robot.","en":"A friend follows the cards exactly like a robot."},"kid":true}$j$::jsonb);
