  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'roller', 0, $j${"id":"roller","emoji":"🛞","name":{"ha":"Robot mai ƙafafu","en":"Rolling robot"},"steps":["cutBody","fixMotor","addWheels","wireSwitch","putBattery","testRun","fixBug"],"result":{"emoji":"🤖","name":{"ha":"Robot mai tafiya","en":"A robot that rolls"}},"summary":{"ha":"Robot mai ƙafafu: jiki, injin, ƙafafu, waya da baturi, sannan gwaji.","en":"Rolling robot: body, motor, wheels, wiring and battery, then a test."}}$j$::jsonb);
