  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"📦","kind":"resource","name":{"ha":"Kwali","en":"Cardboard box"},"why":{"ha":"Tsohon kwali abu na asali ne da za a sake amfani da shi.","en":"Old cardboard is a resource that can be reused."}},{"emoji":"🤖","kind":"product","name":{"ha":"Robot mai ƙafafu","en":"Rolling robot"},"why":{"ha":"An gina shi daga sassa da yawa. Sabon abu ne.","en":"It is built from many parts. It is a new product."}},{"emoji":"🧢","kind":"resource","name":{"ha":"Murfin kwalba","en":"Bottle caps"},"why":{"ha":"Ana iya amfani da su a matsayin ƙafafu. Abu na asali ne.","en":"They can be used as wheels. They are a resource."}},{"emoji":"🦾","kind":"product","name":{"ha":"Hannun robot na ruwa","en":"Hydraulic arm"},"why":{"ha":"An yi shi da kwali da sirinji. Sabon abu ne.","en":"It is made from cardboard and syringes. It is a new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"✏️","kind":"safe","name":{"ha":"Zana shirin robot","en":"Draw a robot plan"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"▶️","kind":"safe","name":{"ha":"Gwada robot a ƙasa, babba yana kusa","en":"Test the robot on the floor with an adult nearby"},"why":{"ha":"Wannan lafiya ne tare da babba.","en":"This is safe with an adult nearby."}},{"emoji":"🔋","kind":"adult","name":{"ha":"Sa baturi ko ƙaramin baturin maɓalli a baki","en":"Put a battery or button battery in your mouth"},"why":{"ha":"Kada ka yi. Yana da haɗari sosai. Ka gaya wa babba.","en":"Never do it. It is very dangerous. Tell an adult."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka kwali da wuƙa mai kaifi","en":"Cut cardboard with a sharp blade"},"why":{"ha":"Kaifi na manya ne kawai.","en":"Sharp tools are for adults only."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Amfani da manne mai zafi ko walda","en":"Use a hot glue gun or solder"},"why":{"ha":"Zafi yana ƙone fata. Babba ne kawai.","en":"Heat burns skin. Only an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Menene robot?","en":"What is a robot?"}$j$::jsonb, $j$[{"ha":"Na’ura da ke bin umarni don yin aiki","en":"A machine that follows instructions to do a job"},{"ha":"Dabbar daji","en":"A wild animal"},{"ha":"Irin abinci","en":"A kind of food"}]$j$::jsonb, 0, $j${"ha":"Robot na’ura ce da mutane suka gina suka shirya ta.","en":"A robot is a machine that people build and program."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me injin yake yi a robot?","en":"What does the motor do in a robot?"}$j$::jsonb, $j$[{"ha":"Yana ba da wuta","en":"It gives power"},{"ha":"Yana ba da motsi","en":"It gives movement"},{"ha":"Yana ba da haske","en":"It gives light"}]$j$::jsonb, 1, $j${"ha":"Injin yana juyawa ya motsa ƙafafu ko sassa.","en":"The motor spins and moves the wheels or parts."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me baturi yake yi?","en":"What does the battery do?"}$j$::jsonb, $j$[{"ha":"Yana yanke kwali","en":"It cuts cardboard"},{"ha":"Yana ɗaure sassa","en":"It holds parts together"},{"ha":"Yana ba da wutar lantarki","en":"It gives electricity"}]$j$::jsonb, 2, $j${"ha":"Baturi yana ba injin wutar da yake buƙata.","en":"The battery gives the motor the power it needs."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me za ka yi da ƙaramin baturin maɓalli?","en":"What do you do with a small button battery?"}$j$::jsonb, $j$[{"ha":"Na riƙe shi a baki","en":"Hold it in my mouth"},{"ha":"Na bar shi, na gaya wa babba","en":"Leave it and tell an adult"},{"ha":"Na jefa shi cikin abinci","en":"Drop it in food"}]$j$::jsonb, 1, $j${"ha":"Ƙaramin baturi yana da haɗari idan an haɗiye shi. Babba ne ke kula da shi.","en":"A small battery is dangerous if swallowed. An adult handles it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Idan umarnin robot ya yi kuskure, me zai faru?","en":"If a robot’s instruction is wrong, what happens?"}$j$::jsonb, $j$[{"ha":"Zai yi kuskure","en":"It will do the wrong thing"},{"ha":"Zai gyara kansa","en":"It fixes itself"},{"ha":"Zai ɓace","en":"It disappears"}]$j$::jsonb, 0, $j${"ha":"Robot yana bin umarni daidai yadda aka rubuta su.","en":"A robot follows instructions exactly as written."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Menene ake kira gyara kuskuren shirin?","en":"What do we call fixing a mistake in a program?"}$j$::jsonb, $j$[{"ha":"Yanka kwali","en":"Cutting cardboard"},{"ha":"Ƙawata","en":"Decorating"},{"ha":"Debugging (gyaran kuskure)","en":"Debugging"}]$j$::jsonb, 2, $j${"ha":"Debugging yana nufin nemo da gyara kuskure a shiri.","en":"Debugging means finding and fixing a mistake in a program."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Wane aiki robot yake taimakawa da shi?","en":"What work do robots help with?"}$j$::jsonb, $j$[{"ha":"Aiki mai nauyi ko mai maimaitawa","en":"Heavy or repeating work"},{"ha":"Cin abinci","en":"Eating food"},{"ha":"Barci","en":"Sleeping"}]$j$::jsonb, 0, $j${"ha":"Robot yana taimaka wa mutane da aiki mai nauyi ko maimaituwa.","en":"Robots help people with heavy or repeating jobs."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🏠","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Iyalin Malam Ali ba su da inda za su wanke hannu kafin cin abinci. Tumatir ɗinsu kuma yana lalacewa da sauri.","en":"Mr Ali’s family has nowhere to wash hands before eating. Their tomatoes also spoil fast."}},{"text":{"ha":"Za ka iya taimaka musu su gina na’urori masu sauƙi?","en":"Can you help them build simple devices?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"♻️","title":{"ha":"Tsofaffin kaya abu na asali ne","en":"Old things are resources"},"lines":[{"text":{"ha":"Kwalbar filastik da tukunyar yumɓu abubuwan asali ne.","en":"A plastic bottle and a clay pot are resources."}},{"text":{"ha":"Idan an sarrafa su, sai su zama na’ura mai magance matsala, sabon abu mai amfani.","en":"When we process them, they become a device that solves a problem, a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"📐","title":{"ha":"Yadda injiniya yake aiki","en":"How an engineer works"},"lines":[{"text":{"ha":"Injiniya yana magance matsala da na’ura.","en":"An engineer solves a problem with a device."}},{"text":{"ha":"Matakai: Matsala → Mafita → Zane → Gini → Gwaji → Gyara.","en":"Steps: Problem → Idea → Design → Build → Test → Improve."}},{"text":{"ha":"Kullum a tambayi mutane abin da suke buƙata kafin a fara.","en":"Always ask people what they need before you start."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kayan aiki masu kaifi, huda da guduma na manya ne kawai.","en":"Sharp tools, drilling and hammers are for adults only."}},{"text":{"ha":"Kada ka yi amfani da wuta ko wutar lantarki ta gida. Ruwan wanke hannu ba na sha ba ne. Wannan wasa ne kawai.","en":"Do not use fire or house electricity. Hand-washing water is not for drinking. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🧼","title":{"ha":"Wurin wanke hannu (tippy tap)","en":"Hand-washing station (tippy tap)"},"lines":[{"k":"whatIs","text":{"ha":"Kwalbar ruwa da aka rataye da igiya a kan sanda.","en":"A water bottle hung with string on a stick frame."}},{"k":"whatDoes","text":{"ha":"Idan ka taka igiya, ruwa yana zubowa ba tare da ka taɓa kwalba ba.","en":"When you step on the string, water pours out without touching the bottle."}},{"k":"whyNeeded","text":{"ha":"Wanke hannu da sabulu yana rage cututtuka.","en":"Washing hands with soap reduces sickness."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🏺","title":{"ha":"Tukunya cikin tukunya (mai sanyaya)","en":"Pot-in-pot cooler"},"lines":[{"k":"whatIs","text":{"ha":"Tukwane biyu da yashi mai ɗanshi a tsakaninsu.","en":"Two pots with damp sand between them."}},{"k":"whatDoes","text":{"ha":"Ruwan yana ƙafewa, sai cikin tukunyar ya yi sanyi.","en":"The water evaporates and the inner pot gets cooler."}},{"k":"whyNeeded","text":{"ha":"Kayan lambu suna daɗewa kafin su lalace.","en":"Vegetables last longer before they spoil."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🌱","title":{"ha":"Kwalbar digar ruwa","en":"Bottle drip watering"},"lines":[{"k":"whatIs","text":{"ha":"Kwalba mai ƙananan ramuka da ake binnewa kusa da shuka.","en":"A bottle with tiny holes buried near a plant."}},{"k":"whatDoes","text":{"ha":"Tana digar ruwa kaɗan-kaɗan zuwa tushen shuka.","en":"It drips a little water to the plant’s roots."}},{"k":"whyNeeded","text":{"ha":"Tana rage ɓarnar ruwa a lokacin rani.","en":"It saves water in the dry season."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🔁","title":{"ha":"Gwaji da gyara","en":"Test and improve"},"lines":[{"text":{"ha":"Bayan gini, a gwada. Ba kowace na’ura ke aiki da kyau a farko ba.","en":"After building, test it. Not every device works well the first time."}},{"text":{"ha":"A canza abu ɗaya a lokaci guda, sannan a sake gwadawa.","en":"Change one thing at a time, then test again."}},{"text":{"ha":"Kuskure yana koya mana.","en":"Mistakes teach us."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Na’ura mai amfani tana da ƙima","en":"A useful device has value"},"lines":[{"text":{"ha":"Na’urar da ke magance matsalar gida za a iya sayarwa ko gyarawa.","en":"A device that solves a home problem can be sold or repaired."}},{"text":{"ha":"Matasa masu ƙirƙira suna iya gina na’urori ga maƙwabta su samu kuɗi.","en":"Young inventors can build devices for neighbours and earn money."}},{"text":{"ha":"Kowanne yana da hanyarsa. Za ka kalle su duka.","en":"Each one has its own way of being made. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'askFamily', 0, $j${"emoji":"🗣️","name":{"ha":"A tambayi iyali","en":"Ask the family"},"text":{"ha":"A tambayi iyali game da matsalar da suke fuskanta a gida.","en":"Ask the family about a problem they face at home."},"kid":true}$j$::jsonb);
