  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Me ya sa ake wanke hannu da sabulu?","en":"Why do we wash hands with soap?"}$j$::jsonb, $j$[{"ha":"Yana rage cututtuka","en":"It reduces sickness"},{"ha":"Yana sa hannu nauyi","en":"It makes hands heavy"},{"ha":"Yana ƙara ƙura","en":"It adds dust"}]$j$::jsonb, 0, $j${"ha":"Sabulu yana cire ƙwayoyin cuta daga hannu.","en":"Soap removes germs from hands."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me tukunya cikin tukunya da yashi mai ɗanshi yake yi?","en":"What does a pot-in-pot with damp sand do?"}$j$::jsonb, $j$[{"ha":"Yana ƙone kayan lambu","en":"It burns vegetables"},{"ha":"Yana haskakawa","en":"It gives light"},{"ha":"Yana sanyaya kayan lambu","en":"It keeps vegetables cooler"}]$j$::jsonb, 2, $j${"ha":"Ruwan da ke ƙafewa yana sanyaya cikin tukunyar.","en":"Water evaporating cools the inner pot."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me za ka yi idan na’ura ba ta yi aiki a gwajin farko?","en":"What do you do if a device does not work on the first test?"}$j$::jsonb, $j$[{"ha":"Na daina","en":"Give up"},{"ha":"Na canza abu ɗaya na sake gwadawa","en":"Change one thing and test again"},{"ha":"Na jefar da ita","en":"Throw it away"}]$j$::jsonb, 1, $j${"ha":"Injiniya yana gyara abu ɗaya a lokaci guda.","en":"Engineers fix one thing at a time."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ke huda da kayan aiki masu kaifi?","en":"Who makes holes with sharp tools?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"}]$j$::jsonb, 0, $j${"ha":"Kaifi na manya ne kawai.","en":"Sharp tools are for adults only."}$j$::jsonb, 5);
